import functools
from typing import ForwardRef, Any
from fastapi.dependencies.utils import get_typed_signature

class A:
    def method(self, x: 'B'):
        return x

class B:
    pass

def wrap(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapper

# The original method has 'B' in its globals
# A.method.__globals__ contains 'B'
# But when wrapped, functools.wraps copies __annotations__
# get_typed_signature uses the globals of the wrapper, not the wrapped function

wrapped_method = wrap(A.method)

# This should not raise NameError
try:
    sig = get_typed_signature(wrapped_method)
    print("Success")
except NameError as e:
    print(f"Caught expected NameError: {e}")
    raise e
