import functools
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature
import types

# Create a mock 'ForwardRef' like object that will fail if not handled correctly
class MockForwardRef:
    def __init__(self, code):
        self.__forward_code__ = code
    def __repr__(self):
        return f"ForwardRef('{self.__forward_code__}')"

def evaluate_forwardref(annotation, globalns, localns):
    if isinstance(annotation, MockForwardRef):
        # This mimics how typing._evaluate works
        eval(annotation.__forward_code__, globalns, localns)
    return annotation

# Mock the evaluate_forwardref in fastapi.dependencies.utils to use our mock
import fastapi.dependencies.utils
fastapi.dependencies.utils.evaluate_forwardref = evaluate_forwardref
fastapi.dependencies.utils.ForwardRef = MockForwardRef

# Now reproduce the scenario
